 <?php $__env->startSection('title','Личный кабинет'); ?> <?php $__env->startSection('content'); ?><section class="dashboard-wrap"><div class="container"><div class="d-flex flex-wrap justify-content-between align-items-end gap-3 mb-4"><div><div class="eyebrow">DRIVER AREA</div><h1>ПРИВЕТ, <span><?php echo e(mb_strtoupper(auth()->user()->name)); ?>.</span></h1><p class="muted">Твоя история заездов и текущие бронирования.</p></div><a class="btn btn-accent" href="<?php echo e(route('booking.create')); ?>">+ Новый заезд</a></div><div class="panel"><div class="panel-head"><h2>МОИ БРОНИРОВАНИЯ</h2><span><?php echo e($bookings->count()); ?> записей</span></div><?php $__empty_1 = true; $__currentLoopData = $bookings; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $booking): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><div class="booking-row"><div><div class="eyebrow">#<?php echo e(str_pad($booking->id,5,'0',STR_PAD_LEFT)); ?> · <?php echo e($booking->start_at->format('d.m.Y H:i')); ?></div><h3><?php echo e($booking->tariff->name); ?></h3><small><?php echo e($booking->participants_count); ?> участн. · <?php echo e($booking->tariff_duration); ?> минут</small></div><div class="text-md-end"><span class="status status-<?php echo e($booking->status); ?>"><?php echo e(['pending'=>'Ожидает','confirmed'=>'Подтверждено','cancelled'=>'Отменено','completed'=>'Завершено','no_show'=>'Неявка'][$booking->status] ?? $booking->status); ?></span><div class="mt-2 fw-bold"><?php echo e(number_format($booking->tariff_price,0,',',' ')); ?> ₽</div></div></div><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><div class="empty-state"><div class="empty-mark">◎</div><h3>ПОКА НЕТ ЗАЕЗДОВ</h3><p>Самое время забронировать первый старт.</p><a href="<?php echo e(route('booking.create')); ?>" class="btn btn-accent">Выбрать время</a></div><?php endif; ?></div></div></section><?php $__env->stopSection(); ?>

